/// lib/segment/src/index/field_index/map_index/payload_index_impl/str.rs:170-222
fn estimate_cardinality_impl<T: MapIndexRead<str>>(
    index: &T,
    condition: &FieldCondition,
    hw_counter: &HardwareCounterCell,
) -> Option<CardinalityEstimation> {
    match &condition.r#match {
        Some(Match::Value(MatchValue { value })) => match value {
            ValueVariants::String(keyword) => {
                let mut estimation = index.match_cardinality(keyword.as_str(), hw_counter);
                estimation.primary_clauses.push(PrimaryCondition::Condition(Box::new(condition.clone())));
                Some(estimation)
            }
            ValueVariants::Integer(_) => None,
            ValueVariants::Bool(_) => None,
        },
        Some(Match::Any(MatchAny { any: any_variant })) => match any_variant {
            AnyVariants::Strings(keywords) => {
                let estimations = keywords.iter().map(|keyword| index.match_cardinality(keyword.as_str(), hw_counter)).collect::<Vec<_>>();
                let estimation = if estimations.is_empty() {
                    CardinalityEstimation::exact(0)
                } else {
                    combine_should_estimations(&estimations, index.get_indexed_points())
                };
                Some(estimation.with_primary_clause(PrimaryCondition::Condition(Box::new(condition.clone()))))
            }
            AnyVariants::Integers(integers) => {
                if integers.is_empty() {
                    Some(CardinalityEstimation::exact(0).with_primary_clause(PrimaryCondition::Condition(Box::new(condition.clone()))))
                } else {
                    None
                }
            }
        },
        Some(Match::Except(MatchExcept { except })) => match except {
            AnyVariants::Strings(keywords) => Some(index.except_cardinality(keywords.iter().map(|k| k.as_str()), hw_counter))
            AnyVariants::Integers(_) => None,
        },
        _ => None,  // <-- BUG: is_empty condition falls through to this None return
    }
}

/// lib/segment/src/index/struct_payload_index/read_view/filtering.rs:104-109
Condition::IsEmpty(IsEmptyCondition { is_empty: field }) => {
    let available_points = self.available_point_count();
    let condition = FieldCondition::new_is_empty(field.key.clone(), true);
    self.estimate_field_condition(&condition, nested_path, hw_counter)?
        .unwrap_or_else(|| CardinalityEstimation::unknown(available_points))  // <-- Falls back to total/2 heuristic
}
